CREATE OR REPLACE FUNCTION public.cancel_test_flight(p_flight uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE f flights%ROWTYPE; c uuid; BEGIN SELECT id INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; SELECT * INTO f FROM flights WHERE id=p_flight AND company_id=c FOR UPDATE; IF NOT FOUND OR f.status NOT IN ('DISPATCHED','EN_ROUTE') THEN RAISE EXCEPTION 'Only active flights can be cancelled'; END IF; UPDATE airport_passenger_pools SET stock=passenger_stock(airport_icao)+f.passengers,updated_at=now() WHERE airport_icao=f.origin_icao; UPDATE flights SET status='CANCELLED' WHERE id=f.id; UPDATE fleet_aircraft SET status='AVAILABLE',location_icao=f.origin_icao WHERE id=f.aircraft_id; END $function$;

CREATE OR REPLACE FUNCTION public.mark_flight_acars(p_flight uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN UPDATE flights SET execution_source='ACARS_AGENT' WHERE id=p_flight AND status='DISPATCHED' AND company_id IN (SELECT id FROM companies WHERE user_id=auth.uid()); IF NOT FOUND THEN RAISE EXCEPTION 'Flight not found'; END IF; END $function$;
REVOKE ALL ON FUNCTION public.mark_flight_acars(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mark_flight_acars(uuid) TO authenticated;